const ACCENT = {
  confirmed: "#2DD4BF",
  deaths: "#FB7185",
  recovered: "#34D399",
  vacc: "#F5A524",
  grid: "#1E2A45",
  panel: "#121A2B",
  panel2: "#0E1626",
  text: "#CBD5E1",
  textDim: "#7E8CA6",
  heading: "#F1F5F9",
};

const MONTH_ORDER = [...new Set(RAW_DATA.map(d => d.m))];
const ALL_STATES = [...new Set(RAW_DATA.map(d => d.st))].sort();
const YEARS = [2020, 2021, 2022];

function fmtNum(n) {
  if (n >= 10000000) return (n / 10000000).toFixed(2) + " Cr";
  if (n >= 100000) return (n / 100000).toFixed(2) + " L";
  if (n >= 1000) return (n / 1000).toFixed(1) + "K";
  return n.toString();
}

function KpiCard({ label, value, sub, accent }) {
  return (
    <div style={{
      background: ACCENT.panel,
      border: `1px solid ${ACCENT.grid}`,
      borderRadius: 10,
      padding: "18px 20px",
      flex: "1 1 200px",
      minWidth: 180,
      position: "relative",
      overflow: "hidden",
    }}>
      <div style={{
        position: "absolute", left: 0, top: 0, bottom: 0, width: 3, background: accent,
      }} />
      <div style={{ fontSize: 12, color: ACCENT.textDim, letterSpacing: 0.3, marginBottom: 8 }}>
        {label}
      </div>
      <div style={{
        fontSize: 28, fontWeight: 700, color: ACCENT.heading,
        fontVariantNumeric: "tabular-nums", lineHeight: 1.1,
      }}>
        {value}
      </div>
      {sub && (
        <div style={{ fontSize: 12, color: accent, marginTop: 6, fontWeight: 500 }}>{sub}</div>
      )}
    </div>
  );
}

function Panel({ title, subtitle, children, style }) {
  return (
    <div style={{
      background: ACCENT.panel,
      border: `1px solid ${ACCENT.grid}`,
      borderRadius: 10,
      padding: "18px 20px 12px",
      ...style,
    }}>
      <div style={{ marginBottom: 4 }}>
        <div style={{ fontSize: 14, fontWeight: 600, color: ACCENT.heading }}>{title}</div>
        {subtitle && <div style={{ fontSize: 11.5, color: ACCENT.textDim, marginTop: 2 }}>{subtitle}</div>}
      </div>
      {children}
    </div>
  );
}

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload || !payload.length) return null;
  return (
    <div style={{
      background: "#0A0F1C", border: `1px solid ${ACCENT.grid}`, borderRadius: 8,
      padding: "10px 12px", fontSize: 12, color: ACCENT.text,
    }}>
      <div style={{ color: ACCENT.heading, fontWeight: 600, marginBottom: 6 }}>{label}</div>
      {payload.map((p, i) => (
        <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 16, color: p.color || p.fill }}>
          <span>{p.name}</span>
          <span style={{ fontWeight: 600 }}>{typeof p.value === "number" ? fmtNum(p.value) : p.value}</span>
        </div>
      ))}
    </div>
  );
};

export default function CovidDashboard() {
  const [yearFilter, setYearFilter] = useState("All");
  const [selectedStates, setSelectedStates] = useState(
    ["Maharashtra", "Kerala", "Uttar Pradesh", "Delhi", "Tamil Nadu"]
  );

  const filteredRaw = useMemo(() => {
    return RAW_DATA.filter(d => yearFilter === "All" || d.y === yearFilter);
  }, [yearFilter]);

  const kpis = useMemo(() => {
    const totalConfirmed = filteredRaw.reduce((s, d) => s + d.nc, 0);
    const totalDeaths = filteredRaw.reduce((s, d) => s + d.nd, 0);
    const totalRecovered = filteredRaw.reduce((s, d) => s + d.nr, 0);
    const cfr = totalConfirmed ? (totalDeaths / totalConfirmed) * 100 : 0;
    const avgVacc =
      filteredRaw.length ? filteredRaw.reduce((s, d) => s + d.vp, 0) / filteredRaw.length : 0;
    return { totalConfirmed, totalDeaths, totalRecovered, cfr, avgVacc };
  }, [filteredRaw]);

  const trendData = useMemo(() => {
    const byMonth = {};
    filteredRaw.forEach(d => {
      if (!selectedStates.includes(d.st)) return;
      if (!byMonth[d.m]) byMonth[d.m] = { m: d.m };
      byMonth[d.m][d.st] = (byMonth[d.m][d.st] || 0) + d.nc;
    });
    return MONTH_ORDER.filter(m => byMonth[m]).map(m => byMonth[m]);
  }, [filteredRaw, selectedStates]);

  const stateBarData = useMemo(() => {
    const byState = {};
    filteredRaw.forEach(d => {
      byState[d.st] = (byState[d.st] || 0) + d.nc;
    });
    return Object.entries(byState)
      .map(([st, val]) => ({ st, val }))
      .sort((a, b) => b.val - a.val)
      .slice(0, 10);
  }, [filteredRaw]);

  const scatterData = useMemo(() => {
    const byState = {};
    filteredRaw.forEach(d => {
      if (!byState[d.st]) byState[d.st] = { st: d.st, nc: 0, nd: 0, hb: d.hb, pop: d.pop };
      byState[d.st].nc += d.nc;
      byState[d.st].nd += d.nd;
    });
    return Object.values(byState).map(s => ({
      st: s.st,
      hb: s.hb,
      cfr: s.nc ? (s.nd / s.nc) * 100 : 0,
      pop: s.pop,
    }));
  }, [filteredRaw]);

  const rankTable = useMemo(() => {
    const byState = {};
    filteredRaw.forEach(d => {
      if (!byState[d.st]) byState[d.st] = { st: d.st, nc: 0, nd: 0, vp: [] };
      byState[d.st].nc += d.nc;
      byState[d.st].nd += d.nd;
      byState[d.st].vp.push(d.vp);
    });
    return Object.values(byState)
      .map(s => ({
        st: s.st,
        nc: s.nc,
        nd: s.nd,
        cfr: s.nc ? (s.nd / s.nc) * 100 : 0,
        vp: Math.max(...s.vp),
      }))
      .sort((a, b) => b.nc - a.nc)
      .slice(0, 8);
  }, [filteredRaw]);

  const lineColors = ["#2DD4BF", "#F5A524", "#FB7185", "#818CF8", "#34D399", "#F472B6", "#38BDF8"];

  const toggleState = (st) => {
    setSelectedStates(prev =>
      prev.includes(st) ? prev.filter(s => s !== st) : [...prev, st].slice(-7)
    );
  };

  return (
    <div style={{
      fontFamily: "'Inter', -apple-system, sans-serif",
      background: "#0B1220",
      minHeight: "100%",
      padding: "22px 22px 32px",
      color: ACCENT.text,
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
        * { box-sizing: border-box; }
        .chip {
          cursor: pointer; user-select: none; transition: all .15s ease;
          padding: 5px 11px; border-radius: 999px; font-size: 12px; font-weight: 500;
          border: 1px solid #1E2A45;
        }
        .yearbtn {
          cursor: pointer; padding: 6px 14px; border-radius: 7px; font-size: 12.5px;
          font-weight: 600; border: 1px solid #1E2A45; background: transparent; color: #7E8CA6;
          transition: all .15s ease;
        }
        .yearbtn.active { background: #2DD4BF; color: #08131A; border-color: #2DD4BF; }
        table.rank { width: 100%; border-collapse: collapse; font-size: 12.5px; }
        table.rank th { text-align: left; color: #7E8CA6; font-weight: 500; padding: 6px 10px; border-bottom: 1px solid #1E2A45; font-size: 11px; }
        table.rank td { padding: 7px 10px; border-bottom: 1px solid #151f33; color: #CBD5E1; }
        table.rank tr:hover td { background: #0E1626; }
      `}</style>

      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 14, marginBottom: 20 }}>
        <div>
          <div style={{ fontSize: 20, fontWeight: 800, color: ACCENT.heading, letterSpacing: -0.3 }}>
            India Public Health &amp; COVID Analytics
          </div>
          <div style={{ fontSize: 12.5, color: ACCENT.textDim, marginTop: 3 }}>
            State-wise trends · Mar 2020 – Dec 2022 · simulated dataset for portfolio use
          </div>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {["All", ...YEARS].map(y => (
            <button
              key={y}
              className={"yearbtn" + (yearFilter === y ? " active" : "")}
              onClick={() => setYearFilter(y)}
            >
              {y}
            </button>
          ))}
        </div>
      </div>

      {/* KPI row */}
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 16 }}>
        <KpiCard label="TOTAL CONFIRMED" value={fmtNum(kpis.totalConfirmed)} accent={ACCENT.confirmed} sub="across 20 states" />
        <KpiCard label="TOTAL DEATHS" value={fmtNum(kpis.totalDeaths)} accent={ACCENT.deaths} sub={`CFR ${kpis.cfr.toFixed(2)}%`} />
        <KpiCard label="TOTAL RECOVERED" value={fmtNum(kpis.totalRecovered)} accent={ACCENT.recovered} sub={`${((kpis.totalRecovered/(kpis.totalConfirmed||1))*100).toFixed(1)}% recovery rate`} />
        <KpiCard label="AVG VACCINATION" value={kpis.avgVacc.toFixed(1) + "%"} accent={ACCENT.vacc} sub="population, at least 1 dose" />
      </div>

      {/* Trend + Bar */}
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 14 }}>
        <Panel
          title="Monthly New Cases — Selected States"
          subtitle="click a chip below to add/remove a state (max 7)"
          style={{ flex: "2 1 480px" }}
        >
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, margin: "8px 0 12px" }}>
            {ALL_STATES.map((st, i) => {
              const active = selectedStates.includes(st);
              const color = lineColors[selectedStates.indexOf(st) % lineColors.length];
              return (
                <div
                  key={st}
                  className="chip"
                  onClick={() => toggleState(st)}
                  style={{
                    background: active ? color + "22" : "transparent",
                    color: active ? color : "#7E8CA6",
                    borderColor: active ? color : "#1E2A45",
                  }}
                >
                  {st}
                </div>
              );
            })}
          </div>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={trendData} margin={{ top: 4, right: 8, left: -12, bottom: 0 }}>
              <CartesianGrid stroke={ACCENT.grid} strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="m" tick={{ fill: ACCENT.textDim, fontSize: 10.5 }} interval={2} axisLine={{ stroke: ACCENT.grid }} tickLine={false} />
              <YAxis tick={{ fill: ACCENT.textDim, fontSize: 10.5 }} tickFormatter={fmtNum} axisLine={false} tickLine={false} />
              <Tooltip content={<CustomTooltip />} />
              {selectedStates.map((st, i) => (
                <Line
                  key={st}
                  type="monotone"
                  dataKey={st}
                  stroke={lineColors[i % lineColors.length]}
                  strokeWidth={2}
                  dot={false}
                  name={st}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </Panel>

        <Panel title="Top 10 States by Confirmed Cases" subtitle="current filter selection" style={{ flex: "1 1 320px" }}>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={stateBarData} layout="vertical" margin={{ top: 4, right: 20, left: 10, bottom: 0 }}>
              <CartesianGrid stroke={ACCENT.grid} strokeDasharray="3 3" horizontal={false} />
              <XAxis type="number" tick={{ fill: ACCENT.textDim, fontSize: 10.5 }} tickFormatter={fmtNum} axisLine={false} tickLine={false} />
              <YAxis type="category" dataKey="st" tick={{ fill: ACCENT.text, fontSize: 11 }} width={95} axisLine={false} tickLine={false} />
              <Tooltip content={<CustomTooltip />} />
              <Bar dataKey="val" name="Confirmed" fill={ACCENT.confirmed} radius={[0, 4, 4, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </Panel>
      </div>

      {/* Scatter + Table */}
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
        <Panel
          title="Health Infrastructure vs Fatality Rate"
          subtitle="hospital beds per lakh (X) vs case fatality rate % (Y) — bubble size = population"
          style={{ flex: "1 1 380px" }}
        >
          <ResponsiveContainer width="100%" height={280}>
            <ScatterChart margin={{ top: 10, right: 20, left: -12, bottom: 4 }}>
              <CartesianGrid stroke={ACCENT.grid} strokeDasharray="3 3" />
              <XAxis type="number" dataKey="hb" name="Beds/Lakh" tick={{ fill: ACCENT.textDim, fontSize: 10.5 }} axisLine={{ stroke: ACCENT.grid }} tickLine={false} label={{ value: "Hospital beds / lakh", position: "insideBottom", offset: -2, fill: ACCENT.textDim, fontSize: 10.5 }} />
              <YAxis type="number" dataKey="cfr" name="CFR %" tick={{ fill: ACCENT.textDim, fontSize: 10.5 }} axisLine={false} tickLine={false} />
              <ZAxis type="number" dataKey="pop" range={[60, 500]} />
              <Tooltip content={<CustomTooltip />} cursor={{ strokeDasharray: "3 3" }} />
              <Scatter data={scatterData} fill={ACCENT.vacc} fillOpacity={0.75} name="States" />
            </ScatterChart>
          </ResponsiveContainer>
        </Panel>

        <Panel title="State Ranking" subtitle="top 8 by total confirmed cases, current filter" style={{ flex: "1 1 380px" }}>
          <table className="rank">
            <thead>
              <tr>
                <th>State</th>
                <th>Confirmed</th>
                <th>CFR %</th>
                <th>Vacc %</th>
              </tr>
            </thead>
            <tbody>
              {rankTable.map(r => (
                <tr key={r.st}>
                  <td style={{ fontWeight: 600, color: ACCENT.heading }}>{r.st}</td>
                  <td>{fmtNum(r.nc)}</td>
                  <td style={{ color: r.cfr > 1.4 ? ACCENT.deaths : ACCENT.text }}>{r.cfr.toFixed(2)}%</td>
                  <td style={{ color: ACCENT.vacc }}>{r.vp.toFixed(1)}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Panel>
      </div>

      <div style={{ marginTop: 18, fontSize: 11, color: ACCENT.textDim, textAlign: "center" }}>
        Data is a realistic simulated dataset built for portfolio/practice — not official government statistics.
      </div>
    </div>
  );
}
